287	}
288	
289	// ---- people ----------------------------------------------------------------------------------
290	
291	export function row(page: Page, personId: string): Locator {
292	  return page.getByTestId(`person-row-${personId}`);
293	}
294	
295	function rows(page: Page): Locator {
296	  return page.locator('[data-testid^="person-row-"]');
297	}
298	
299	function rowsNamed(page: Page, name: string): Locator {
300	  const re = new RegExp(`^\\s*${escapeRe(name.trim())}(\\s\\([^()]*\\))?\\s*$`, 'i');

