import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** `today` (yyyy-MM-dd) is the sheet's own date: every date decision and default uses it, never the clock.
 *  An `archived` sheet stays visible but the server refuses every change to it. */
export type Sheet = { id: string; today: string; archived: boolean };

/** Every per-sheet query key starts with ['sheet', id], so loading a sheet re-reads all of it. */
export const sheetKey = (id: string) => ['sheet', id] as const;

export function useSheet(id: string) {
  return useQuery({
    queryKey: sheetKey(id),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(id)}`),
    enabled: id !== '',
  });
}

/** The sheet's today (yyyy-MM-dd), or undefined while the sheet loads. Use it for every default date. */
export function useSheetToday(id: string): string | undefined {
  return useSheet(id).data?.today;
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { type Sheet, sheetKey, useSheet } from './sheet';

function SheetToday() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const loaded = useSheet(sheet);
  const [input, setInput] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today, user }),
    // A new today changes every date decision on the sheet: re-read all of it.
    onSuccess: () => queryClient.invalidateQueries({ queryKey: sheetKey(sheet) }),
  });
  const submit = useSubmitOnce(save);
  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/archive`, { user }),
    onSuccess: (archived) => queryClient.setQueryData(sheetKey(sheet), archived),
  });
  const submitArchive = useSubmitOnce(archive);
  // The sheet's one error element: a refused today or a refused archive, whichever was tried last.
  const failed = save.isError ? save.error : archive.isError ? archive.error : null;

  if (!user || !loaded.data) return null;
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        archive.reset();
        submit(input.trim());
      }}
    >
      Today <strong data-testid="sheet-today">{loaded.data.today}</strong>{' '}
      <input
        data-testid="sheet-today-input"
        type="date"
        value={input}
        onChange={(e) => {
          setInput(e.target.value);
          save.reset();
          archive.reset();
        }}
      />
      <button type="submit" data-testid="sheet-today-save">
        Set today
      </button>
      {' '}Archived <strong data-testid="sheet-archived">{loaded.data.archived ? 'yes' : 'no'}</strong>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        onClick={() => {
          save.reset();
          submitArchive();
        }}
      >
        Archive sheet
      </button>
      {failed && (
        <span data-testid="sheet-error" role="alert">
          {' '}{failed instanceof HttpError && failed.reason ? failed.reason : 'Not a valid date.'}
        </span>
      )}
    </form>
  );
}

export const contribution = AppHeader.fill({ order: 20, Component: SheetToday });
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { sheetKey, useSheet } from './sheet';

function SheetPicker() {
  const [user] = useCurrentUser();
  const [sheet, setSheet] = useCurrentSheet();
  const [input, setInput] = useState('');
  const queryClient = useQueryClient();
  const loaded = useSheet(sheet);

  if (!user) return null;
  return (
    <form
      data-testid="sheet-form"
      onSubmit={(e) => {
        e.preventDefault();
        const id = input.trim();
        if (!id) return;
        // Loading an id again re-reads it from the store.
        void queryClient.invalidateQueries({ queryKey: sheetKey(id) });
        setSheet(id);
      }}
    >
      <input data-testid="sheet-id-input" placeholder="Sheet id" value={input} onChange={(e) => setInput(e.target.value)} />
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
      {loaded.data && (
        <span>
          {' '}Sheet <strong data-testid="sheet-current-id">{loaded.data.id}</strong>
        </span>
      )}
    </form>
  );
}

export const contribution = AppHeader.fill({ order: 10, Component: SheetPicker });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A refused request; `reason` is the text the server answered with (empty when none). */
export class HttpError extends Error {
  constructor(message: string, readonly reason: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    const reason = await res.text().catch(() => '');
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, reason, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
