190	        this.rates = rates;
191	    }
192	
193	    /** The rates as they stood at the end of the date (see {@link History}), to read only. */
194	    public RateStore asOf(LocalDate date) {
195	        return new RateStore(jdbc, History.asOf("rate", "sheet_id, grade, from_date", date));
196	    }
197	
198	    /** Every rate on the sheet, by grade then from-date. */
199	    public List<RateResponse> list(String sheetId) {
200	        return jdbc.query("SELECT grade, pct, from_date, to_date FROM " + rates + " WHERE sheet_id = ? ORDER BY grade, from_date",
201	                (rs, i) -> {
202	                    LocalDate from = rs.getObject("from_date", LocalDate.class);
203	                    return RateResponse.of(rs.getString("grade"), rs.getBigDecimal("pct"),
204	                            START.equals(from) ? null : from, rs.getObject("to_date", LocalDate.class));
205	                }, sheetId);
206	    }
207	
208	    /** The grade's percent in force on the date (the rate with the latest from-date on or before it),
209	     *  or null when no rate of the grade applies then, or that rate ended (its to-date) before it. */
210	    public BigDecimal find(String sheetId, String grade, LocalDate on) {
211	        List<BigDecimal> found = jdbc.query(
212	                "SELECT pct, to_date FROM " + rates + " WHERE sheet_id = ? AND grade = ? AND from_date <= ? ORDER BY from_date DESC LIMIT 1",
213	                (rs, i) -> {
214	                    LocalDate to = rs.getObject("to_date", LocalDate.class);
215	                    return to != null && to.isBefore(on) ? null : rs.getBigDecimal("pct");
216	                }, sheetId, grade, on);
217	        return found.isEmpty() ? null : found.get(0);
218	    }
219	
220	    /** Whether the grade's rate that would apply on the date (the one with the latest from-date on or
221	     *  before it) ended (its to-date) before it. */
222	    public boolean ended(String sheetId, String grade, LocalDate on) {
223	        List<LocalDate> found = jdbc.query(
224	                "SELECT to_date FROM " + rates + " WHERE sheet_id = ? AND grade = ? AND from_date <= ? ORDER BY from_date DESC LIMIT 1",
225	                (rs, i) -> rs.getObject("to_date", LocalDate.class), sheetId, grade, on);
226	        return !found.isEmpty() && found.get(0) != null && found.get(0).isBefore(on);
227	    }
228	
229	    /** Whether the grade's rate in force on the date ends before {@code today}: its to-date, or the day
230	     *  before the grade's next rate starts, whichever is first, is before it. */
231	    public boolean endsBefore(String sheetId, String grade, LocalDate on, LocalDate today) {
232	        List<LocalDate> to = jdbc.query(
233	                "SELECT to_date FROM " + rates + " WHERE sheet_id = ? AND grade = ? AND from_date <= ? ORDER BY from_date DESC LIMIT 1",
234	                (rs, i) -> rs.getObject("to_date", LocalDate.class), sheetId, grade, on);
235	        if (to.isEmpty()) {
236	            return false;
237	        }
238	        if (to.get(0) != null && to.get(0).isBefore(today)) {
239	            return true;
240	        }
241	        List<LocalDate> next = jdbc.queryForList(
242	                "SELECT from_date FROM " + rates + " WHERE sheet_id = ? AND grade = ? AND from_date > ? ORDER BY from_date LIMIT 1",
243	                LocalDate.class, sheetId, grade, on);
244	        return !next.isEmpty() && !next.get(0).isAfter(today);
245	    }
246	
247	    /** Sets the grade's rate from the date (null for from the beginning of time) through the to-date
248	     *  (null for no end), replacing any there. */
249	    public void set(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
250	        jdbc.update("MERGE INTO rate (sheet_id, grade, from_date, to_date, pct) KEY (sheet_id, grade, from_date) VALUES (?, ?, ?, ?, ?)",
251	                sheetId, grade, from == null ? START : from, to, pct);
252	    }
253	}
