324	    /** Whether a period on the sheet shares a day with from..to (inclusive). */
325	    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
326	        Integer n = jdbc.queryForObject(
327	                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?", Integer.class,
328	                sheetId, to, from);
329	        return n != null && n > 0;
330	    }
