332	    public void add(String sheetId, PeriodInput period) {
333	        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)", sheetId,
334	                period.name(), period.from(), period.to());
335	    }
336	
337	    /** Each person's due-total fixed when the period was closed, by person id. */
338	    private Map<Long, BigDecimal> personTotals(String sheetId, String name) {
339	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
340	        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_name = ? ORDER BY person_id",
341	                rs -> {
342	                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
343	                }, sheetId, name);
344	        return totals;
345	    }
346	
347	    /** Fixes each person's due-total in the period as it is when it is closed. */
348	    public void fixPersonTotals(String sheetId, String name, Map<Long, BigDecimal> totals) {
349	        totals.forEach((personId, total) -> jdbc.update(
350	                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
351	                sheetId, name, personId, total));
352	    }
353	
354	    /** Drops each person's due-total fixed in the period (as a soft close fixed them, before they are fixed afresh). */
355	    public void dropPersonTotals(String sheetId, String name) {
356	        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?", sheetId, name);
357	    }
358	
359	    /** Closes the open (or soft-closed) period with its due-total fixed; false when it is already closed
360	     *  (another user closed it first). */
361	    public boolean close(String sheetId, String name, BigDecimal total) {
362	        return jdbc.update("UPDATE period SET closed = TRUE, soft = FALSE, closed_total = ? "
363	                + "WHERE sheet_id = ? AND name = ? AND NOT closed", total, sheetId, name) == 1;
364	    }
365	
366	    /** Soft-closes the open period with its due-total fixed; false when it is already closed or soft-closed. */
367	    public boolean softClose(String sheetId, String name, BigDecimal total) {
368	        return jdbc.update("UPDATE period SET soft = TRUE, closed_total = ? "
369	                + "WHERE sheet_id = ? AND name = ? AND NOT closed AND NOT soft", total, sheetId, name) == 1;
370	    }
371	
372	    /** Reopens the closed or soft-closed period, dropping its fixed due-total; false when it is neither
373	     *  (another user reopened it first). */
374	    public boolean reopen(String sheetId, String name) {
375	        dropPersonTotals(sheetId, name);
376	        return jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL "
377	                + "WHERE sheet_id = ? AND name = ? AND (closed OR soft)", sheetId, name) == 1;
378	    }
379	}
