573	/** Each claim's status log, oldest first: a line per status it has had,
574	 *  {@code <STATUS> by <user> on <sheet's today> due=<due as computed then, n/a when no rate applied>}. */
575	@Repository
576	public class ClaimLogStore {
577	
578	    private final JdbcTemplate jdbc;
579	    private final ClaimStore claims;
580	    private final PersonStore people;
581	    private final RateStore rates;
582	    private final SettingStore settings;
583	    private final SheetStore sheets;
584	
585	    public ClaimLogStore(JdbcTemplate jdbc, ClaimStore claims, PersonStore people, RateStore rates,
586	            SettingStore settings, SheetStore sheets) {
587	        this.jdbc = jdbc;
588	        this.claims = claims;
589	        this.people = people;
590	        this.rates = rates;
591	        this.settings = settings;
592	        this.sheets = sheets;
593	    }
594	
595	    /** Logs the claim's current status, by the user, on the sheet's today, at its due as the screen
596	     *  works it out now (its settled due once settled, else its figure plus any late charge). */
597	    public void record(Claim claim, String user) {
598	        String sheetId = claim.getSheetId();
599	        LocalDate today = sheets.today(sheetId);
600	        Person person = people.find(sheetId, claim.getPersonId());
601	        BigDecimal pct = person == null ? null
602	                : rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
603	        BigDecimal due = Lateness.of(sheetId, settings, sheets, claims).due(claim, pct);
604	        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, log_date, due) VALUES (?, ?, ?, ?, ?, ?)",
605	                sheetId, claim.getId(), claim.getStatus().name(), user, Date.valueOf(today),
606	                due == null ? "n/a" : due.setScale(2).toPlainString());
607	    }
608	
609	    /** Every claim's log lines on the sheet, by claim id, oldest first. */
610	    public Map<Long, List<String>> lines(String sheetId) {
611	        Map<Long, List<String>> lines = new HashMap<>();
612	        jdbc.query("SELECT * FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
613	            lines.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>())
614	                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
615	                            + rs.getObject("log_date", LocalDate.class) + " due=" + rs.getString("due"));
616	        }, sheetId);
617	        return lines;
618	    }
619	
620	    /** Each claim's status at the end of the date, by claim id, as its log records it: the last status
621	     *  logged on or before the date. A claim logged only after it (added after it) is absent. */
622	    public Map<Long, ClaimStatus> statusesAt(String sheetId, LocalDate date) {
623	        Map<Long, ClaimStatus> statuses = new HashMap<>();
624	        jdbc.query("SELECT claim_id, status FROM claim_log WHERE sheet_id = ? AND log_date <= ? ORDER BY id", rs -> {
625	            statuses.put(rs.getLong("claim_id"), ClaimStatus.valueOf(rs.getString("status")));
626	        }, sheetId, Date.valueOf(date));
627	        return statuses;
628	    }
629	
630	    /** The sheet's today on which the claim was last logged SETTLED; null when it never was. */
631	    public LocalDate settledOn(Claim claim) {
632	        List<LocalDate> dates = jdbc.query("SELECT log_date FROM claim_log WHERE sheet_id = ? AND claim_id = ? "
633	                + "AND status = ? ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getObject("log_date", LocalDate.class),
634	                claim.getSheetId(), claim.getId(), ClaimStatus.SETTLED.name());
635	        return dates.isEmpty() ? null : dates.get(0);
636	    }
637	
638	    /** The claim's log lines, oldest first. */
639	    public List<String> lines(Claim claim) {
640	        return lines(claim.getSheetId()).getOrDefault(claim.getId(), List.of());
641	    }
