package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.util.ArrayList;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import net.officefloor.hq.app.history.History;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, in the order they were added, each with their dated grades. */
@Repository
public class PersonStore {

    private final JdbcTemplate jdbc;

    public PersonStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The people's grades on the sheet (only the one person when {@code personId} is given), by person. */
    private Map<Long, NavigableMap<LocalDate, String>> grades(String sheetId, Long personId, String table) {
        Map<Long, NavigableMap<LocalDate, String>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, grade FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId), rs -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
                            .put(rs.getObject("from_date", LocalDate.class), rs.getString("grade"));
                }, sheetId);
        return grades;
    }

    /** The people's holds on the sheet (only the one person's when {@code personId} is given), by person, oldest first. */
    private Map<Long, List<Hold>> holds(String sheetId, Long personId, String table) {
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM " + table + " WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
                    holds.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new Hold(
                            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
                }, sheetId);
        return holds;
    }

    private List<Person> query(String sheetId, Long personId, String sql, Object... args) {
        return queryFrom(sheetId, personId, "person_grade", "person_hold", sql, args);
    }

    private List<Person> queryFrom(String sheetId, Long personId, String gradeTable, String holdTable, String sql,
            Object... args) {
        Map<Long, NavigableMap<LocalDate, String>> grades = grades(sheetId, personId, gradeTable);
        Map<Long, List<Hold>> holds = holds(sheetId, personId, holdTable);
        RowMapper<Person> row = (rs, i) -> {
            Person p = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                    grades.getOrDefault(rs.getLong("id"), new TreeMap<>()), rs.getLong("version"),
                    rs.getObject("retired_from", LocalDate.class), holds.getOrDefault(rs.getLong("id"), List.of()));
            p.setTerms(rs.getObject("terms", Integer.class));
            return p;
        };
        return jdbc.query(sql, row, args);
    }

    public List<Person> list(String sheetId) {
        return query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? ORDER BY id", sheetId);
    }

    public Person find(String sheetId, long id) {
        List<Person> found = query(sheetId, id, "SELECT * FROM person WHERE sheet_id = ? AND id = ?", sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person as they stood at the end of the date, with their grades and holds then (see {@link History});
     *  null when they were not on the sheet then. */
    public Person findAsOf(String sheetId, long id, LocalDate date) {
        List<Person> found = queryFrom(sheetId, id, History.asOf("person_grade", "person_id, from_date", date),
                History.asOf("person_hold", "id", date),
                "SELECT * FROM " + History.asOf("person", "id", date) + " WHERE sheet_id = ? AND id = ?", sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name, ignoring case and the spaces around it; null when none. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? AND name_key = LOWER(?)",
                sheetId, name.trim());
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this name, ignoring case. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name.trim(), exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Adds the person with their first grade, which applies from the beginning of time, and no terms of their own. */
    public Person add(String sheetId, String name, String grade) {
        return add(sheetId, name, grade, null);
    }

    /** Adds the person with their first grade, which applies from the beginning of time, and their own
     *  terms (null for none). */
    public Person add(String sheetId, String name, String grade, Integer terms) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, terms) VALUES (?, ?, ?)", new String[] { "ID" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setObject(3, terms, java.sql.Types.INTEGER);
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)", sheetId,
                id, Person.START, grade);
        Person person = new Person(id, sheetId, name, new TreeMap<>(Map.of(Person.START, grade)), 0);
        person.setTerms(terms);
        return person;
    }

    /**
     * Stores the person over the version it was loaded at, moving the version on; false (nothing
     * stored) when someone else has stored another version since. The grade the edit records (if any)
     * is kept with the ones already recorded, replacing one from the same date.
     */
    public boolean save(Person person) {
        int n = jdbc.update(
                "UPDATE person SET name = ?, terms = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
                person.getName(), person.getTerms(), person.getSheetId(), person.getId(), person.getVersion());
        if (n == 1) {
            person.setVersion(person.getVersion() + 1);
            LocalDate from = person.getRecordFrom();
            if (from != null) {
                jdbc.update("MERGE INTO person_grade (sheet_id, person_id, from_date, grade) KEY (person_id, from_date)"
                        + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getGrades().get(from));
            }
        }
        return n == 1;
    }

    /** Retires the person from the date. An edit of their name or grade leaves it as it is. */
    public void retire(Person person, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?", from, person.getSheetId(),
                person.getId());
        person.setRetiredFrom(from);
    }

    /** Adds a hold to the person's holds. An edit of their name or grade leaves them as they are. */
    public void hold(Person person, Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), hold.from(), hold.to());
        person.addHold(hold);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The rates for each grade, kept per sheet, each applying from its from-date through its to-date
 *  (if it has one). A rate with no from-date applies from the beginning of time (stored as
 *  {@link #START}). A grade with no rate is absent. */
@Repository
public class RateStore {

    /** The stored from-date of a rate that applies from the beginning of time. */
    private static final LocalDate START = LocalDate.of(1, 1, 1);

    private final JdbcTemplate jdbc;

    /** Where the rates are read from: the rate table, or the rates as they stood at the end of a date. */
    private final String rates;

    @Autowired
    public RateStore(JdbcTemplate jdbc) {
        this(jdbc, "rate");
    }

    private RateStore(JdbcTemplate jdbc, String rates) {
        this.jdbc = jdbc;
        this.rates = rates;
    }

    /** The rates as they stood at the end of the date (see {@link History}), to read only. */
    public RateStore asOf(LocalDate date) {
        return new RateStore(jdbc, History.asOf("rate", "sheet_id, grade, from_date", date));
    }

    /** Every rate on the sheet, by grade then from-date. */
    public List<RateResponse> list(String sheetId) {
        return jdbc.query("SELECT grade, pct, from_date, to_date FROM " + rates + " WHERE sheet_id = ? ORDER BY grade, from_date",
                (rs, i) -> {
                    LocalDate from = rs.getObject("from_date", LocalDate.class);
                    return RateResponse.of(rs.getString("grade"), rs.getBigDecimal("pct"),
                            START.equals(from) ? null : from, rs.getObject("to_date", LocalDate.class));
                }, sheetId);
    }

    /** The grade's percent in force on the date (the rate with the latest from-date on or before it),
     *  or null when no rate of the grade applies then, or that rate ended (its to-date) before it. */
    public BigDecimal find(String sheetId, String grade, LocalDate on) {
        List<BigDecimal> found = jdbc.query(
                "SELECT pct, to_date FROM " + rates + " WHERE sheet_id = ? AND grade = ? AND from_date <= ? ORDER BY from_date DESC LIMIT 1",
                (rs, i) -> {
                    LocalDate to = rs.getObject("to_date", LocalDate.class);
                    return to != null && to.isBefore(on) ? null : rs.getBigDecimal("pct");
                }, sheetId, grade, on);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the grade's rate that would apply on the date (the one with the latest from-date on or
     *  before it) ended (its to-date) before it. */
    public boolean ended(String sheetId, String grade, LocalDate on) {
        List<LocalDate> found = jdbc.query(
                "SELECT to_date FROM " + rates + " WHERE sheet_id = ? AND grade = ? AND from_date <= ? ORDER BY from_date DESC LIMIT 1",
                (rs, i) -> rs.getObject("to_date", LocalDate.class), sheetId, grade, on);
        return !found.isEmpty() && found.get(0) != null && found.get(0).isBefore(on);
    }

    /** Whether the grade's rate in force on the date ends before {@code today}: its to-date, or the day
     *  before the grade's next rate starts, whichever is first, is before it. */
    public boolean endsBefore(String sheetId, String grade, LocalDate on, LocalDate today) {
        List<LocalDate> to = jdbc.query(
                "SELECT to_date FROM " + rates + " WHERE sheet_id = ? AND grade = ? AND from_date <= ? ORDER BY from_date DESC LIMIT 1",
                (rs, i) -> rs.getObject("to_date", LocalDate.class), sheetId, grade, on);
        if (to.isEmpty()) {
            return false;
        }
        if (to.get(0) != null && to.get(0).isBefore(today)) {
            return true;
        }
        List<LocalDate> next = jdbc.queryForList(
                "SELECT from_date FROM " + rates + " WHERE sheet_id = ? AND grade = ? AND from_date > ? ORDER BY from_date LIMIT 1",
                LocalDate.class, sheetId, grade, on);
        return !next.isEmpty() && !next.get(0).isAfter(today);
    }

    /** Sets the grade's rate from the date (null for from the beginning of time) through the to-date
     *  (null for no end), replacing any there. */
    public void set(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        jdbc.update("MERGE INTO rate (sheet_id, grade, from_date, to_date, pct) KEY (sheet_id, grade, from_date) VALUES (?, ?, ?, ?, ?)",
                sheetId, grade, from == null ? START : from, to, pct);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The periods on each sheet. */
@Repository
public class PeriodStore {

    private final RowMapper<PeriodResponse> ROW = (rs, i) -> PeriodResponse.of(rs.getString("name"),
            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class),
            rs.getBoolean("closed"), rs.getBigDecimal("closed_total"),
            rs.getBoolean("closed") || rs.getBoolean("soft") ? personTotals(rs.getString("sheet_id"), rs.getString("name"))
                    : Map.of(),
            rs.getBoolean("soft"));

    private final JdbcTemplate jdbc;

    public PeriodStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every period on the sheet, by from-date. */
    public List<PeriodResponse> list(String sheetId) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
    }

    /** The period on the sheet with this name, or null when there is none. */
    public PeriodResponse find(String sheetId, String name) {
        List<PeriodResponse> found = jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name = ?", ROW, sheetId,
                name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The closed period on the sheet whose dates contain the date, or null when none does. */
    public PeriodResponse closedOn(String sheetId, LocalDate date) {
        List<PeriodResponse> found = jdbc.query(
                "SELECT * FROM period WHERE sheet_id = ? AND closed AND from_date <= ? AND to_date >= ?", ROW, sheetId,
                date, date);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether the period on the sheet whose dates contain the date is soft-closed. */
    public boolean softOn(String sheetId, LocalDate date) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND soft AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, date, date);
        return n != null && n > 0;
    }

    /** The period on the sheet whose dates contain the date, or null when none does. */
    public PeriodResponse on(String sheetId, LocalDate date) {
        List<PeriodResponse> found = jdbc.query(
                "SELECT * FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?", ROW, sheetId, date, date);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether a period on the sheet has this name, ignoring case. */
    public boolean nameTaken(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND LOWER(name) = LOWER(?)",
                Integer.class, sheetId, name);
        return n != null && n > 0;
    }

    /** Whether a period on the sheet shares a day with from..to (inclusive). */
    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?", Integer.class,
                sheetId, to, from);
        return n != null && n > 0;
    }

    public void add(String sheetId, PeriodInput period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)", sheetId,
                period.name(), period.from(), period.to());
    }

    /** Each person's due-total fixed when the period was closed, by person id. */
    private Map<Long, BigDecimal> personTotals(String sheetId, String name) {
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_name = ? ORDER BY person_id",
                rs -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                }, sheetId, name);
        return totals;
    }

    /** Fixes each person's due-total in the period as it is when it is closed. */
    public void fixPersonTotals(String sheetId, String name, Map<Long, BigDecimal> totals) {
        totals.forEach((personId, total) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                sheetId, name, personId, total));
    }

    /** Drops each person's due-total fixed in the period (as a soft close fixed them, before they are fixed afresh). */
    public void dropPersonTotals(String sheetId, String name) {
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?", sheetId, name);
    }

    /** Closes the open (or soft-closed) period with its due-total fixed; false when it is already closed
     *  (another user closed it first). */
    public boolean close(String sheetId, String name, BigDecimal total) {
        return jdbc.update("UPDATE period SET closed = TRUE, soft = FALSE, closed_total = ? "
                + "WHERE sheet_id = ? AND name = ? AND NOT closed", total, sheetId, name) == 1;
    }

    /** Soft-closes the open period with its due-total fixed; false when it is already closed or soft-closed. */
    public boolean softClose(String sheetId, String name, BigDecimal total) {
        return jdbc.update("UPDATE period SET soft = TRUE, closed_total = ? "
                + "WHERE sheet_id = ? AND name = ? AND NOT closed AND NOT soft", total, sheetId, name) == 1;
    }

    /** Reopens the closed or soft-closed period, dropping its fixed due-total; false when it is neither
     *  (another user reopened it first). */
    public boolean reopen(String sheetId, String name) {
        dropPersonTotals(sheetId, name);
        return jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL "
                + "WHERE sheet_id = ? AND name = ? AND (closed OR soft)", sheetId, name) == 1;
    }
}
