import { asString, useSearchParam } from '../url/useSearchParam';

// The signed-in name and the active sheet id live in the URL (`user`, `sheet`), so every feature
// reads them directly and each browser tab is its own session.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
import { useMutationState, useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';
import { sheetKey } from '../sheet/sheet';

/** `version` moves on with each stored edit; an edit is saved only over the version its editor loaded.
 *  `statementCount` is how many statements were taken of them; `statedTotal` (two decimals, or n/a)
 *  and `statementDate` (yyyy-MM-dd) are the last one's, null when none was taken. `retired` is set
 *  as soon as a `retiredFrom` date (yyyy-MM-dd, null when not retired) is, whatever the date;
 *  `retiredNow` once the sheet's today reaches it: from then their OPEN claims count in no live total
 *  unless a statement bound them, as a hold's would.
 *  `holds` are their holds, oldest first; `held` whether they have any. Their OPEN claims dated within
 *  a hold count in no live total unless a statement bound them; their SETTLED ones still do.
 *  `patronIds` are the ids of the other people on the sheet they named as their patrons.
 *  `grade` is the grade in force on the sheet's today; `grades` every grade with the date it applies from.
 *  `terms` are their own terms in whole days (null when none), ahead of their grade's and the sheet's. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: Grades;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  retiredNow: boolean;
  held: boolean;
  holds: Hold[];
  patronIds: number[];
  terms: number | null;
};

/** A hold from its from-date to its to-date (yyyy-MM-dd, both inclusive; null for no end). */
export type Hold = { from: string; to: string | null };

/** Whether the hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => h.from <= date && (h.to === null || date <= h.to);

export const GRADES = ['A', 'B', 'C'] as const;

/** A person's grades, each with the date (yyyy-MM-dd) it applies from; the first has none (null),
 *  applying from the beginning of time. */
export type Grades = { grade: string; from: string | null }[];

/** The grade in force on the date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(grades: Grades, on: string | undefined): string {
  let best = grades[0];
  for (const g of grades) {
    if (g.from === null || (on !== undefined && g.from <= on)) {
      if ((best.from ?? '') <= (g.from ?? '')) best = g;
    }
  }
  return best?.grade ?? 'A';
}

/** Under the sheet's key, so loading the sheet again re-reads its people. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

export function usePeople(sheet: string) {
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: sheet !== '',
  });
}

/** The id of the person whose editor is open in the person form ('' when it adds). */
export const useEditingPerson = () => useSearchParam('editPerson', asString);

/** Whether the people list shows retired people too; off when the screen is first opened. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);

/** The mutation key of an action on a person's row (a statement, a hold, a retirement): the row
 *  shows only the error of the latest one taken, so taking the next action clears an earlier one's. */
export const personActionKey = (sheet: string, personId: number) => [...peopleKey(sheet), personId, 'action'] as const;

/** When the latest action on the person's row was taken (0 when none was). */
export function useLatestPersonAction(sheet: string, personId: number): number {
  const taken = useMutationState({
    filters: { mutationKey: personActionKey(sheet, personId) },
    select: (m) => m.state.submittedAt,
  });
  return Math.max(0, ...taken);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';
import { asNumber, asString, useSearchParam } from '../../url/useSearchParam';
import { type Hold, covers } from '../people/people';

/** PENDING: settled by a clerk above the clerk limit, awaiting a steward's approval; handled as OPEN,
 *  except that a statement does not bind it while it is PENDING. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** Every status the summary and header count, whether or not a claim can reach it. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const satisfies readonly ClaimStatus[];

/** How many of these claims have the status. */
export const statusCount = (claims: Claim[] | undefined, status: ClaimStatus) =>
  (claims ?? []).filter((c) => c.status === status).length;

/** `amount` has two decimals; `date` is yyyy-MM-dd; `number` is given when the claim is opened
 *  (null for a draft or a voided claim): the sheet-wide 1, 2, ... or, numbered per period, <period>-<n> / X-<n>. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  /** The due fixed when the claim was settled; null when it has none, so its due follows the rate. */
  due: string | null;
  /** The user who opened the claim; null until it is opened. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim to its figure then. */
  stated: boolean;
  /** The figure the claim was bound to; null when not bound, or bound while it had none. */
  statedDue: string | null;
  /** Whether the statement bound the claim to n/a: the rate that would apply to it had ended (its to-date). */
  statedNa: boolean;
  /** The number of the settled claim a correction (a negative amount) corrects; null for any other claim. */
  corrects: string | null;
  /** The date (yyyy-MM-dd) its live figures round by: its own, or for a correction that of the claim it corrects. */
  roundsBy: string;
  /** The date (yyyy-MM-dd) it is due by, fixed when it was added from the terms of its person's grade then. */
  dueBy: string;
  /** Its status log, oldest first: `<STATUS> by <user> on <date> due=<due>`, one line per status it has had. */
  log: string[];
  /** Whether it is deferred on the sheet's today: OPEN and deferred until a date after it. Until then it
   *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
  deferred: boolean;
  /** The date (yyyy-MM-dd) it was last deferred until; null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs it has: a claim due above the proof threshold on its date cannot be settled or approved with none. */
  proofs: number;
  /** The number of the claim it was split off; null when it was not split off another. */
  splitFrom: string | null;
  /** Whether it was added while the period its date falls in was soft-closed. */
  lateEntry: boolean;
};

/** A correction: a claim with a negative amount, which has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.amount.trim().startsWith('-') && Number(c.amount) !== 0;

/** Whether the claim is open: OPEN, or PENDING, which is handled as open. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/** Only OPEN, PENDING and SETTLED claims count toward claimed and the totals; a deferred claim does not. */
export const counts = (c: Claim) => (isOpen(c) && !c.deferred) || c.status === 'SETTLED';

/** Whether the claim keeps the figure (or n/a) its person's last statement bound it to: not while PENDING. */
export const isBound = (c: Claim) => c.stated && (c.statedDue !== null || c.statedNa) && c.status !== 'PENDING';

/** These claims less the OPEN (or PENDING) claims dated within one of their person's holds, or of a
 *  person whose retirement date the sheet's today has reached, which count in no live total, unless a
 *  statement bound them. */
export const live = (claims: Claim[], people: { id: number; holds: Hold[]; retiredNow: boolean }[] | undefined) => {
  const byId = new Map((people ?? []).map((p) => [p.id, p]));
  return claims.filter((c) => {
    const p = byId.get(c.personId);
    return !(isOpen(c) && !c.stated && p !== undefined && (p.retiredNow || p.holds.some((h) => covers(h, c.date))));
  });
};

/** The date (yyyy-MM-dd) the given number of days before this one. */
const daysBefore = (date: string, days: number) => {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - days);
  return d.toISOString().slice(0, 10);
};

/** Whether a person is active on the date (yyyy-MM-dd): one of their claims (already filtered to those
 *  live) is OPEN or PENDING, counts, and is dated within the 30 days up to and including the date. */
export const isActive = (claims: Claim[], today: string | undefined) =>
  today !== undefined &&
  claims.some((c) => isOpen(c) && counts(c) && c.date > daysBefore(today, 30) && c.date <= today);

/** Whether the claim is SETTLED and dated within the 90 days up to and including the date (yyyy-MM-dd). */
export const isRecentSettled = (c: Claim, today: string | undefined) =>
  today !== undefined && c.status === 'SETTLED' && c.date > daysBefore(today, 90) && c.date <= today;

/** Under the sheet's key, so loading the sheet again re-reads its claims. */
export const claimsKey = (sheet: string) => [...sheetKey(sheet), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function useClaims(sheet: string) {
  return useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: sheet !== '',
  });
}

/** Amounts are added in whole cents, so the sum is exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** The sum of the amounts of those of these claims that count, with two decimals. */
export function claimed(claims: Claim[]): string {
  return (claims.filter(counts).reduce((sum, c) => sum + cents(c.amount), 0) / 100).toFixed(2);
}

/** The ids of the claims selected for a bulk action, kept in the URL (`selectedClaims`, comma separated). */
export function useSelectedClaims(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('selectedClaims', asString);
  const ids = raw.split(',').filter((s) => s !== '').map(Number).filter((n) => !Number.isNaN(n));
  return [ids, (next) => setRaw(next.join(','))];
}

/** The id of the claim whose editor is open, and locked by this user, kept in the URL (`editClaim`). */
export const useEditingClaim = () => useSearchParam('editClaim', asNumber);
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';

/** The sheet's settings: `clerkLimit` (two decimals) is the most due a clerk may settle a claim at,
 *  null for no limit; `floor` (two decimals) is the least a claim's live due may be; `terms` is the
 *  whole days after its date a claim is due by; `latePct` (two decimals) is the percent of an overdue
 *  claim's figure charged at each full 30 days it is overdue (the one in force on that boundary); `policyDate` (yyyy-MM-dd) is the date
 *  rounding turns on, null when blank (then the sheet's today); `periodNumberingFrom` (yyyy-MM-dd) is the
 *  date from which claims opened are numbered per period, null when blank (off); `gradeTerms` is the terms
 *  in force for each grade (its own, else the sheet's), by grade; `cap` (two decimals) is the most a person's
 *  due-total may be, null for no cap; `proofThreshold` (two decimals) is the due above which a claim needs a proof
 *  before it is settled or approved, null for none. Each of these that carries a figure is the one in force on the sheet's today.
 *  `floorFrom` and `latePctFrom` are the floor and late percent recorded, oldest from-date (yyyy-MM-dd) first:
 *  a claim's floor and late percent are those in force on its date. `perms` is the permission matrix: the roles
 *  that may take each action (open, settle, void, reassign, close, reopen), comma separated, by action; null when
 *  blank (the standing rule). `graceDays` is the whole days after its to-date an open period is closed when the
 *  sheet's today moves, null when blank (off). */
export type Settings = { clerkLimit: string | null; floor: string; terms: string; latePct: string; policyDate: string | null;
  periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null; proofThreshold: string | null;
  floorFrom: Dated[]; latePctFrom: Dated[]; perms: Record<string, string | null>;
  graceDays: string | null };

/** A setting's value recorded from a date (yyyy-MM-dd); a null value is blank. */
export type Dated = { from: string; value: string | null };

/** The floor a sheet has before any is recorded. */
const STARTING_FLOOR = '1.00';

/** The late percent a sheet has before any is recorded. */
const STARTING_LATE_PCT = '0.00';

/** The value in force on the date: the one with the latest from-date on or before it, else `starting`. */
export function valueOn(history: Dated[], date: string, starting: string): string {
  let found: string | null = null;
  for (const d of history) if (d.from <= date) found = d.value;
  return found ?? starting;
}

/** The floor in force on each date; undefined until the settings are read. */
export function floorOf(settings: Settings | undefined): ((date: string) => string) | undefined {
  return settings && ((date) => valueOn(settings.floorFrom, date, STARTING_FLOOR));
}

/** The late percent in force on each date; undefined until the settings are read. */
export function latePctOf(settings: Settings | undefined): ((date: string) => string) | undefined {
  return settings && ((date) => valueOn(settings.latePctFrom, date, STARTING_LATE_PCT));
}

/** Under the sheet's key, so loading the sheet again re-reads its settings. */
export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;

export function useSettings(sheet: string) {
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: sheet !== '',
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';
import { type Claim, type ClaimStatus, isOpen } from '../claims/claims';
import { covers } from '../people/people';
import type { Person } from '../people/people';
import { type Floor, type Late, type Rate, claimDue, dueTotal } from '../rates/rates';

/** A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd, inclusive), whether
 *  it is closed and, once closed, the due-total fixed on closing (null while open) and each person's
 *  due-total fixed on closing, by person id (empty while open), and whether it is soft-closed: not closed,
 *  but with those figures fixed as when it was soft-closed. No two periods on a sheet overlap. */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  total: string | null;
  people: Record<string, string>;
  soft: boolean;
};

/** Whether the period's figures are fixed: it is closed or soft-closed. */
export const isFixed = (period: Period) => period.closed || period.soft;

/** Under the sheet's key, so loading the sheet again re-reads its periods. */
export const periodsKey = (sheet: string) => [...sheetKey(sheet), 'periods'] as const;

/** Every period on the sheet, by from-date. */
export function usePeriods(sheet: string) {
  return useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: sheet !== '',
  });
}

/** Whether the date (yyyy-MM-dd) falls in the period. */
export const contains = (period: Period, date: string) => period.from <= date && date <= period.to;

/** The period whose dates contain the date, or undefined when none does. */
export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
  return (periods ?? []).find((p) => contains(p, date));
}

/** The claim's status at the end of the day (yyyy-MM-dd), as its status log records it (each line
 *  dated the sheet's today when the change was made); null when it had not been added by then. */
export function statusAt(claim: Claim, date: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of claim.log ?? []) {
    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
    if (m && m[2] <= date) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether the claim counts toward a period: by the status it had at the end of the period's last
 *  day it was OPEN, PENDING or SETTLED; and, as the live rules say, it is not deferred on the sheet's
 *  today, nor (while open then and still open now, and unbound by a statement) dated within one of its person's holds
 *  or of a person whose retirement date the sheet's today has reached. */
export function countsInPeriod(claim: Claim, period: Period, person: Person): boolean {
  const status = statusAt(claim, period.to);
  if (status === 'SETTLED') return true;
  if (status !== 'OPEN' && status !== 'PENDING') return false;
  return !claim.deferred && (claim.stated || !isOpen(claim) || !(person.retiredNow || person.holds.some((h) => covers(h, claim.date))));
}

/** A person's due-total for a period: once closed or soft-closed, the figure fixed then (0.00 for a person
 *  added since); else the sum of the figures (as shown now) of their claims whose date falls in it
 *  and that count by their status at the period's end, skipping n/a. */
export function personPeriodDue(
  period: Period,
  person: Person,
  claims: Claim[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  if (isFixed(period)) return period.people?.[String(person.id)] ?? '0.00';
  return dueTotal(
    (claims ?? [])
      .filter((c) => c.personId === person.id && contains(period, c.date) && countsInPeriod(c, period, person))
      .map((c) => claimDue(c, rates, person.grades, floor, late)),
  );
}

/** A period's due-total as the list shows it: the sum of the people's due-totals for it. */
export function periodDue(
  period: Period,
  claims: Claim[] | undefined,
  people: Person[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  return dueTotal((people ?? []).map((p) => personPeriodDue(period, p, claims, rates, floor, late)));
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';

/** Under the sheet's key, so loading the sheet again re-reads who the user watches. */
export const watchesKey = (sheet: string, user: string) => [...sheetKey(sheet), 'watches', user] as const;

/** The ids of the people the signed-in user watches on the sheet. */
export function useWatches(sheet: string, user: string) {
  return useQuery({
    queryKey: watchesKey(sheet, user),
    queryFn: () =>
      getJson<number[]>(`/api/sheets/${encodeURIComponent(sheet)}/watches?user=${encodeURIComponent(user)}`),
    enabled: sheet !== '',
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';

/** A user name's role on the sheet. A name with none assigned is a clerk; a viewer may change nothing. */
export type Role = { user: string; role: string };

export const ROLES = ['clerk', 'steward', 'viewer'] as const;

/** Under the sheet's key, so loading the sheet again re-reads its roles. */
export const rolesKey = (sheet: string) => [...sheetKey(sheet), 'roles'] as const;

export function useRoles(sheet: string) {
  return useQuery({
    queryKey: rolesKey(sheet),
    queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheet)}/roles`),
    enabled: sheet !== '',
  });
}

/** The steward role delegated to `user` by the steward `by` for from..to (yyyy-mm-dd), inclusive. */
export type Delegation = { user: string; from: string; to: string; by: string };

export const delegationsKey = (sheet: string) => [...sheetKey(sheet), 'delegations'] as const;

export function useDelegations(sheet: string) {
  return useQuery({
    queryKey: delegationsKey(sheet),
    queryFn: () => getJson<Delegation[]>(`/api/sheets/${encodeURIComponent(sheet)}/delegations`),
    enabled: sheet !== '',
  });
}
import { type Claim, isOpen } from '../claims/claims';
import { type Floor, type Late, type Rate, claimDue, dueTotal } from '../rates/rates';
import { type Settings, latePctOf } from '../settings/settings';
import type { Grades } from '../people/people';

/** The claim's due-by (yyyy-MM-dd): fixed when it was added, from the terms of its person's grade then. */
export const dueBy = (claim: Claim): string => claim.dueBy;

/** Whether the claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by is before the sheet's today. */
export function overdue(claim: Claim, today: string | undefined): boolean {
  return isOpen(claim) && !claim.deferred && today !== undefined && dueBy(claim) < today;
}

const DAY = 24 * 60 * 60 * 1000;

/** How many full 30 days the claim is overdue on the sheet's today (0 when it is not overdue). */
export function latePeriods(claim: Claim, today: string | undefined): number {
  if (today === undefined || !overdue(claim, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${dueBy(claim)}T00:00:00Z`)) / DAY;
  return Math.floor(days / 30);
}

/** The 30-day boundaries (yyyy-MM-dd) the claim is overdue past on the sheet's today: its due-by plus 30, 60, 90 ... days. */
export function lateBoundaries(claim: Claim, today: string | undefined): string[] {
  const start = Date.parse(`${dueBy(claim)}T00:00:00Z`);
  return Array.from({ length: latePeriods(claim, today) }, (_, i) =>
